package org.humanjourney.core.geography.map;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.server.players.PlayerList;
import net.minecraft.world.level.Level;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.npc.context.*;
import org.humanjourney.core.npc.economy.EconomyCatalog;

class MapServerTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void nativeRegistries(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void closeLoader(){loader.close();}
 MinecraftServer server;SavedDiscovery saved;List<ServerPlayer> online;Map<UUID,Set<String>> tags;Map<UUID,List<MapPackets.Frame>> sent;Map<UUID,GeographyContext> views;Map<UUID,Double> positions;AtomicInteger clock;String era;
 MockedStatic<SavedDiscovery> saves;MockedStatic<MapNetwork> network;MockedStatic<GeographyNetwork> hud;MockedStatic<GeographyServer> runtime;
 @BeforeEach void setup(){GeographyServer.clear();NpcContextStore.reset();server=mock(MinecraftServer.class);var players=mock(PlayerList.class);online=new ArrayList<>();tags=new HashMap<>();sent=new HashMap<>();views=new HashMap<>();positions=new HashMap<>();clock=new AtomicInteger(10);era="era_test";saved=new SavedDiscovery();when(server.getPlayerList()).thenReturn(players);when(players.getPlayers()).thenAnswer(i->online);when(server.getTickCount()).thenAnswer(i->clock.get());saves=mockStatic(SavedDiscovery.class,i->i.getMethod().getName().equals("get")?saved:i.callRealMethod());network=mockStatic(MapNetwork.class);network.when(()->MapNetwork.send(any(),any())).thenAnswer(i->{ServerPlayer p=i.getArgument(1);sent.get(p.getUUID()).add(i.getArgument(0));return true;});hud=mockStatic(GeographyNetwork.class);hud.when(()->GeographyNetwork.send(any(),any())).thenReturn(true);runtime=mockStatic(GeographyServer.class,i->{if(i.getMethod().getName().equals("era"))return era;if(i.getMethod().getName().equals("context")){ServerPlayer p=i.getArgument(0);return views.get(p.getUUID());}return i.callRealMethod();});catalog(false);}
 @AfterEach void close(){runtime.close();hud.close();network.close();saves.close();GeographyServer.clear();NpcContextStore.reset();}
 void catalog(boolean changed){var macro=MapGeometryTest.nativeArea("macro",0,"none",Map.of("era_later","Later Macro"),changed?200:100);var local=MapGeometryTest.nativeArea("local",0,"macro",Map.of(),changed?40:20);var geo=new NpcGeography(List.of(macro),List.of(local));NpcContextStore.accept(new NpcContextStore.Data(new EraRules(List.of()),geo,Map.of(),Map.of(),0,EconomyCatalog.empty()));}
 ServerPlayer player(String name,String... roles){var p=mock(ServerPlayer.class);var level=mock(ServerLevel.class);var id=UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8));tags.put(id,new HashSet<>(List.of(roles)));sent.put(id,new ArrayList<>());views.put(id,new GeographyContext("macro","Macro","local","Local"));positions.put(id,0D);when(p.getUUID()).thenReturn(id);when(p.getId()).thenReturn(online.size()+1);when(p.getScoreboardName()).thenReturn(name);when(p.getTags()).thenAnswer(i->tags.get(id));when(p.level()).thenReturn(level);when(level.dimension()).thenReturn(Level.OVERWORLD);when(level.getServer()).thenReturn(server);when(p.getX()).thenAnswer(i->positions.get(id));when(p.getZ()).thenReturn(0D);online.add(p);return p;}
 void tick(){GeographyServer.tick(server);clock.addAndGet(10);}
 ClientMapState client(ServerPlayer p){var c=new ClientMapState();sent.get(p.getUUID()).forEach(c::accept);return c;}
 @Test void teacherMovementCannotRevealButStudentDiscoveryUpdatesAllParticipants(){var teacher=player("teacher","hj_teacher","hj_student","hj_participant");var outsider=player("outsider");tick();assertTrue(saved.snapshot().locals().isEmpty());assertTrue(client(teacher).snapshot().areas().isEmpty());positions.put(teacher.getUUID(),20D);tick();assertTrue(saved.snapshot().locals().isEmpty());var student=player("student","hj_student","hj_participant");tick();assertEquals(2,client(teacher).snapshot().areas().size());assertEquals(2,client(student).snapshot().areas().size());assertTrue(sent.get(outsider.getUUID()).isEmpty());}
 @Test void unchangedMovementDoesNotResendGeometryAndJoiningGetsFullKnowledge(){var student=player("student","hj_student","hj_participant");tick();int count=sent.get(student.getUUID()).size();for(int i=0;i<20;i++){positions.put(student.getUUID(),i+1D);tick();}assertEquals(count,sent.get(student.getUUID()).size());var second=player("second","hj_student","hj_participant");tick();assertEquals(MapPackets.Mode.FULL,sent.get(second.getUUID()).getFirst().mode());assertEquals(client(student).snapshot().areas(),client(second).snapshot().areas());}
 @Test void adminMarkAndResetAreImmediateAndDelayedStateCannotReturn(){var teacher=player("teacher","hj_teacher","hj_participant");tick();var delta=saved.mark(DiscoveryLedger.Kind.MACRO,"macro");GeographyServer.publish(server,delta,new GeographyContext("macro","Macro","",""),false);assertEquals(1,client(teacher).snapshot().areas().size());delta=saved.mark(DiscoveryLedger.Kind.LOCAL,"local");GeographyServer.publish(server,delta,new GeographyContext("macro","Macro","local","Local"),false);assertEquals(2,client(teacher).snapshot().areas().size());saved.reset();GeographyServer.resync(server);var c=client(teacher);assertTrue(c.snapshot().areas().isEmpty());c.accept(sent.get(teacher.getUUID()).get(1));assertTrue(c.snapshot().areas().isEmpty());}
 @Test void acceptedReloadUpdatesShapesAndRemovalPurgesCache(){var student=player("student","hj_student","hj_participant");tick();var c=client(student);int before=sent.get(student.getUUID()).size();catalog(true);tick();var list=sent.get(student.getUUID());list.subList(before,list.size()).forEach(c::accept);assertTrue(c.snapshot().index().hover(MapGeometryTest.DIM,30,30).primary().contains("local"));NpcContextStore.accept(new NpcContextStore.Data(new EraRules(List.of()),NpcGeography.empty(),Map.of(),Map.of(),0,EconomyCatalog.empty()));before=list.size();tick();list.subList(before,list.size()).forEach(c::accept);assertTrue(c.snapshot().areas().isEmpty());assertTrue(MapServer.describe(student).contains("stale/unresolvable=1/1"));}
 @Test void eraLabelChangeRefreshesWithoutChangingDiscovery(){var p=player("student","hj_student","hj_participant");tick();long revision=saved.snapshot().revision();int before=sent.get(p.getUUID()).size();era="era_later";tick();var frames=sent.get(p.getUUID()).subList(before,sent.get(p.getUUID()).size());assertEquals(MapPackets.Mode.FULL,frames.getFirst().mode());assertEquals(revision,saved.snapshot().revision());assertEquals("Later Macro",client(p).snapshot().areas().get(new MapArea.Key(MapArea.Kind.MACRO,"macro")).label());}
 @Test void roleLossClearsMapAndRejoinGetsFreshSnapshot(){var p=player("student","hj_student","hj_participant");tick();tags.get(p.getUUID()).clear();tick();assertTrue(client(p).snapshot().areas().isEmpty());tags.get(p.getUUID()).addAll(Set.of("hj_teacher","hj_participant"));tick();assertEquals(2,client(p).snapshot().areas().size());}
 @Test void rejectedReloadPreservesGeometryAndResyncRequestsAreRateLimited(){var p=player("student","hj_student","hj_participant");tick();int before=sent.get(p.getUUID()).size();NpcContextStore.reject("synthetic invalid geography");tick();assertEquals(before,sent.get(p.getUUID()).size());MapServer.request(p);tick();assertEquals(before+1,sent.get(p.getUUID()).size());MapServer.request(p);tick();assertEquals(before+1,sent.get(p.getUUID()).size());clock.addAndGet(60);MapServer.request(p);tick();assertEquals(before+2,sent.get(p.getUUID()).size());}
}
